<?php
declare(strict_types=1);
require dirname(__DIR__).'/private/CatalogStore.php';require dirname(__DIR__).'/private/PublicationRunner.php';
use BotanikArt\{CatalogStore,PublicationRunner};
function checkRemoval(bool $ok,string $message):void{if(!$ok)throw new RuntimeException($message);}
$root=sys_get_temp_dir().'/ba-removals-'.bin2hex(random_bytes(6));mkdir($root.'/data',0700,true);$dir=$root.'/api/.private';mkdir($dir,0700,true);
try{
 file_put_contents($root.'/data/catalog.json',json_encode(['products'=>[['id'=>'flowwow-fixture','source'=>'flowwow','title'=>'Fixture','description'=>'Fixture','price'=>500,'catalogGroup'=>'plant','status'=>'ready','images'=>['https://content2.flowwow-images.com/fixture.jpg']]]]));$photo='assets/uploads/catalogue/'.str_repeat('a',32).'.jpg';mkdir($root.'/assets/uploads/catalogue',0700,true);file_put_contents($root.'/'.$photo,'fixture');$s=new CatalogStore($dir.'/catalogue',$root.'/data/catalog.json');$ids=[];
 foreach(['Parent','Member','Active','Pending'] as $i=>$title){$id=$s->save(['title'=>$title,'description'=>'Fixture','price'=>500,'status'=>'ready','catalogGroup'=>'plant','images'=>[$photo]]);$ids[]=$id;$c=$s->channels($id)['avito'];$c=array_replace($c,['enabled'=>true,'management'=>'site','externalId'=>(string)(111+max(0,$i-1)),'state'=>$i===3?'awaiting_report':'published']);$s->db->prepare("UPDATE product_channels SET document=? WHERE product_id=? AND channel='avito'")->execute([json_encode($c),$id]);}
 $before=$s->publicCatalog();$flow=$s->channels($ids[0])['flowwow'];$calls=[];
 $r=new PublicationRunner($s,$dir,null,function($method,$path)use(&$calls){$calls[]=[$method,$path];checkRemoval($method==='GET'&&str_starts_with($path,'/core/v1/items?'),'Removal check wrote to Avito');return ['resources'=>[['id'=>111,'status'=>'removed'],['id'=>112,'status'=>'active'],['id'=>113,'status'=>'old']]];});
 $out=$r->reconcileAvitoRemovals();checkRemoval($out['disabled']===1,'Shared listing was not handled once');checkRemoval(!$s->channels($ids[0])['avito']['enabled']&&!$s->channels($ids[1])['avito']['enabled'],'Shared members still enabled');checkRemoval($s->channels($ids[2])['avito']['enabled'],'Active listing disabled');checkRemoval($s->channels($ids[3])['avito']['enabled'],'Explicit pending publication was cancelled');checkRemoval($s->publicCatalog()===$before&&$s->channels($ids[0])['flowwow']===$flow,'Website or Flowwow changed');
 $r->reconcileAvitoRemovals();checkRemoval($s->channels($ids[0])['avito']['state']==='removed_external','Removal did not persist');
 $r=new PublicationRunner($s,$dir,null,fn()=>throw new RuntimeException('HTTP 503'));try{$r->reconcileAvitoRemovals();throw new LogicException('Outage was not propagated');}catch(RuntimeException $e){checkRemoval($e->getMessage()==='HTTP 503','Unexpected error');}checkRemoval($s->channels($ids[2])['avito']['enabled'],'Outage treated as removal');
 $r=new PublicationRunner($s,$dir,null,function()use($s,$ids){$s->db->prepare('UPDATE products SET version=version+1 WHERE id=?')->execute([$ids[2]]);return ['resources'=>[['id'=>112,'status'=>'removed']]];});$r->reconcileAvitoRemovals();checkRemoval($s->channels($ids[2])['avito']['enabled'],'Stale response overwrote a newer edit');
 $uploads=0;$r=new PublicationRunner($s,$dir,null,function($method,$path,$body)use(&$uploads){checkRemoval($method==='POST'&&$path==='/autoload/v1/upload','Wrong upload trigger');$uploads++;return [];});$meta=new ReflectionMethod($r,'uploadMeta');$flush=new ReflectionMethod($r,'flushAvitoUpload');$meta->invoke($r,'avito:uploadPending',time());$flush->invoke($r);$flush->invoke($r);checkRemoval($uploads===1,'Upload request replayed');
 $meta->invoke($r,'avito:uploadAttempt',0);$meta->invoke($r,'avito:uploadPending',time());$r=new PublicationRunner($s,$dir,null,function()use(&$uploads){$uploads++;throw new RuntimeException('Timeout');});$flush->invoke($r);$flush->invoke($r);checkRemoval($uploads===2&&$meta->invoke($r,'avito:uploadPending')>0,'Ambiguous trigger was replayed or lost');
 echo "Avito removals passed: authoritative status, shared membership, website/Flowwow preservation, pending intent, outages, concurrency and persistence.\n";
}finally{$it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($root,FilesystemIterator::SKIP_DOTS),RecursiveIteratorIterator::CHILD_FIRST);foreach($it as $f)$f->isDir()?rmdir($f->getPathname()):unlink($f->getPathname());rmdir($root);}
